   486  int ptls_buffer_reserve(ptls_buffer_t *buf, size_t delta)
   487  {
   488      if (buf->base == NULL)
   489          return PTLS_ERROR_NO_MEMORY;
   490
   491      if (PTLS_MEMORY_DEBUG || buf->capacity < buf->off + delta) {
   492          uint8_t *newp;
   493          size_t new_capacity = buf->capacity;
   494          if (new_capacity < 1024)
   495              new_capacity = 1024;
   496          while (new_capacity < buf->off + delta) {
   497              new_capacity *= 2;
   498          }
   499          if ((newp = malloc(new_capacity)) == NULL)
   500              return PTLS_ERROR_NO_MEMORY;
   501          memcpy(newp, buf->base, buf->off);
   502          ptls_buffer__release_memory(buf);
   503          buf->base = newp;
   504          buf->capacity = new_capacity;
   505          buf->is_allocated = 1;
   506      }
   507
   508      return 0;
   509  }
